# Generated by build.py from recipe.yml for recipe http-download-a-file-in-parallel-ranges. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'slow-site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'fetch-in-ranges.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Fetches a file as four byte ranges at once, then joins and checks them.`n# Usage: sh fetch-in-ranges.sh <url>`nurl=`$1`n`n# The size, from a HEAD request.`nsize=`$(curl -s -f -I -o /dev/null -w `"%header{content-length}`" `"`$url`")`npart=`$(( (size + 3) / 4 ))`n`n# Four ranges, the last one cut at the end of the file; one curl, four transfers at once.`nr0=`"0-`$(( part - 1 ))`"`nr1=`"`$part-`$(( 2 * part - 1 ))`"`nr2=`"`$(( 2 * part ))-`$(( 3 * part - 1 ))`"`nr3=`"`$(( 3 * part ))-`$(( size - 1 ))`"`nw=`"%{http_code} %header{content-range} %{num_connects}\n`"`ncurl --parallel --parallel-immediate \`n  -s -f -w `"`$w`" -r `"`$r0`" -o part0 `"`$url`" --next \`n  -s -f -w `"`$w`" -r `"`$r1`" -o part1 `"`$url`" --next \`n  -s -f -w `"`$w`" -r `"`$r2`" -o part2 `"`$url`" --next \`n  -s -f -w `"`$w`" -r `"`$r3`" -o part3 `"`$url`" > ranges.txt || exit`nsort ranges.txt`n`nsh check.sh part0 part1 part2 part3`n")
[IO.File]::WriteAllText((Join-Path $PWD 'check.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Joins the parts in the order given and compares the result with the original.`n# Usage: sh check.sh <part>...`ncat `"`$@`" > joined`necho `"joined: `$(wc -c < joined | tr -d `" `") bytes`"`nif cmp -s joined site/big.bin; then echo `"identical`"; else echo `"differs`"; exit 1; fi`n")
cmd /c 'head -c 1000000 /dev/urandom > site/big.bin'
cmd /c 'cp site/big.bin slow-site/big.bin'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh fetch-in-ranges.sh http://127.0.0.1:8080/big.bin } finally { Stop-Process $server0 }
